package edu.ku.commerce.omnichannel_commerce.order; import jakarta.persistence.*; import lombok.*; import java.math.*;
@Entity @Table(name="purchase_orders") @Getter @Setter @NoArgsConstructor public class PurchaseOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long customerId; private String channel; @Enumerated(EnumType.STRING) private OrderStatus status; @Column(precision=19,scale=2) private BigDecimal subtotal; @Column(precision=19,scale=2) private BigDecimal tax; @Column(precision=19,scale=2) private BigDecimal discount; @Column(precision=19,scale=2) private BigDecimal total; private String customerName; private String customerEmail; private String customerPhone; @Column(length=1000) private String customerAddress; private String paymentMethod; private java.time.Instant createdAt=java.time.Instant.now(); @Version private Long version; }
